import React, { useState, useContext } from 'react';
import { AuthContext } from '../context/AuthContext';
import Header from '../components/header';
import HomeImg from "../imagenes/undraw_beach_day_cser.png";
import "./home.css";

const Home = () => {
  const { user } = useContext(AuthContext);
  const userId = user?.id; // acá tenés el id automático
  console.log(userId);


  const [ubicacion, setUbicacion] = useState(null);
  const [error, setError] = useState(null);

  const obtenerUbicacion = () => {
    if (!navigator.geolocation) {
      setError('Geolocalización no soportada por el navegador');
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        setUbicacion({ latitude, longitude });
        setError(null);

        if (!userId) {
  setError('Usuario no logueado');
  return;
}

fetch(`http://localhost:3000/api/users/${userId}`, {
  method: 'PUT',
  headers: {
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    location: {
      latitude,
      longitude,
    },
  }),
})
        .then(response => response.json())
        .then(data => {
          console.log('Ubicación actualizada:', data);
        })
        .catch(err => {
          console.error('Error al actualizar ubicación:', err);
          setError('Error al actualizar la ubicación en el servidor');
        });
      },
      () => {
        setError('No se pudo obtener la ubicación');
      }
    );
  };

  return (
    <div className='bodyHome'>
      <div className='contenedorHome'>
        <img src={HomeImg} alt="Logo" className='imagenHome'/>
        <h1 className='tituloHome'>Pet Finder App</h1>
        <p className='textoHome'>Encontrá y reportá mascotas perdidas cerca de tu ubicación</p>
      </div>
      <div className="contenedorboteneshome">
        <button className='botonUnoHome' onClick={obtenerUbicacion}>Dar mi ubicación actual</button>
        <button className='botonDosHome'>¿Cómo funciona Pet Finder?</button>
      </div>
      {ubicacion && (
        <p>Ubicación: Latitud {ubicacion.latitude}, Longitud {ubicacion.longitude}</p>
      )}
      {error && <p style={{ color: 'red' }}>{error}</p>}
    </div>
  );
};

export default Home;
